it("should oscillate a vertical blinker into a horizontal blinker", () => {
  const result = nextGeneration([
    [0, 0],
    [0, 1],
    [0, 2],
  ]);
  expect(result).toHaveLength(3);
  expect(result).toContainEqual([-1, 1]);
  expect(result).toContainEqual([0, 1]);
  expect(result).toContainEqual([1, 1]);
});
